 static uint[] cursorIds={32512,32651,32650,32514,32515,32513,32631,32648,32645,32644,32642,32643,32646,32516,32649,32671,32672};
 static void ApplySize(string dest,int size){for(int i=0;i<roles.Length;i++){IntPtr h=LoadImage(IntPtr.Zero,Path.Combine(dest,files[i]),2,size,size,0x10);if(h==IntPtr.Zero)throw new Exception("Não foi possível carregar "+files[i]);if(!SetSystemCursor(h,cursorIds[i])){DestroyCursor(h);if(i<15&&i!=6)throw new Exception("Não foi possível aplicar o tamanho em "+roles[i]);}}}
 static string root=AppDomain.CurrentDomain.BaseDirectory;
