 void Run(Action a){UseWaitCursor=true;try{a();status.Text="Pronto! Cursor atualizado.";}catch(Exception e){MessageBox.Show(e.Message,"Cursor Cores",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{UseWaitCursor=false;}}
 static byte[] CursorImage(byte[] src,Color color,int size){
  int count=BitConverter.ToUInt16(src,4), best=0,dist=int.MaxValue;for(int i=0;i<count;i++){int w=src[6+i*16];if(w==0)w=256;int dd=Math.Abs(w-size);if(dd<dist){dist=dd;best=i;}}
  int entry=6+best*16,len=BitConverter.ToInt32(src,entry+8),off=BitConverter.ToInt32(src,entry+12);int oldWidth=src[entry]==0?256:src[entry],oldHeight=src[entry+1]==0?256:src[entry+1];
  using(var ms=new MemoryStream(src,off,len))using(var im=Image.FromStream(ms))using(var bm=new Bitmap(size,size,PixelFormat.Format32bppArgb)){
   using(var g=Graphics.FromImage(bm)){g.DrawImage(im,0,0,size,size);}for(int y=0;y<size;y++)for(int x=0;x<size;x++){var p=bm.GetPixel(x,y);if(p.A>0&&p.R-p.B>25&&p.G-p.B>15){float shade=Math.Max(p.R,p.G)/255f;bm.SetPixel(x,y,Color.FromArgb(p.A,(int)(color.R*shade),(int)(color.G*shade),(int)(color.B*shade)));}}
   using(var png=new MemoryStream()){bm.Save(png,ImageFormat.Png);byte[] bytes=png.ToArray();using(var output=new MemoryStream())using(var w=new BinaryWriter(output)){w.Write((ushort)0);w.Write((ushort)2);w.Write((ushort)1);w.Write((byte)size);w.Write((byte)size);w.Write((ushort)0);w.Write((ushort)(BitConverter.ToUInt16(src,entry+4)*size/oldWidth));w.Write((ushort)(BitConverter.ToUInt16(src,entry+6)*size/oldHeight));w.Write(bytes.Length);w.Write(22);w.Write(bytes);return output.ToArray();}}
  }
 }
 static byte[] Chunks(byte[] src,int start,int end,Color c,int size){using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){for(int p=start;p+8<=end;){string id=Encoding.ASCII.GetString(src,p,4);int n=BitConverter.ToInt32(src,p+4);if(n<0||p+8+n>end)throw new InvalidDataException("Animação inválida.");byte[] payload;if(id=="icon"){byte[] cur=new byte[n];Array.Copy(src,p+8,cur,0,n);payload=CursorImage(cur,c,size);}else if(id=="LIST"){byte[] sub=Chunks(src,p+12,p+8+n,c,size);payload=new byte[4+sub.Length];Array.Copy(src,p+8,payload,0,4);Array.Copy(sub,0,payload,4,sub.Length);}else{payload=new byte[n];Array.Copy(src,p+8,payload,0,n);}w.Write(Encoding.ASCII.GetBytes(id));w.Write(payload.Length);w.Write(payload);if(payload.Length%2!=0)w.Write((byte)0);p+=8+n+(n%2);}return m.ToArray();}}
 static byte[] ConvertFile(string path,Color c,int size){byte[] b;using(var resource=typeof(CursorCores).Assembly.GetManifestResourceStream("Base."+Path.GetFileName(path)))using(var buffer=new MemoryStream()){if(resource==null)throw new FileNotFoundException("Recurso interno ausente: "+Path.GetFileName(path));resource.CopyTo(buffer);b=buffer.ToArray();}if(Path.GetExtension(path)==".cur")return CursorImage(b,c,size);byte[] chunks=Chunks(b,12,b.Length,c,size);using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(chunks.Length+4);w.Write(Encoding.ASCII.GetBytes("ACON"));w.Write(chunks);return m.ToArray();}}
 static void Backup(){Directory.CreateDirectory(data);string backup=Path.Combine(data,"anterior.dat");if(File.Exists(backup))return;using(var k=Registry.CurrentUser.OpenSubKey(@"Control Panel\Cursors"))using(var w=new BinaryWriter(File.Create(backup))){foreach(string r in roles){object v=k.GetValue(r,null,RegistryValueOptions.DoNotExpandEnvironmentNames);w.Write(v!=null);w.Write(v as string??"");w.Write(v==null?1:(int)k.GetValueKind(r));}}}
 static void BackupSize(){string p=Path.Combine(data,"tamanho-anterior.txt");if(File.Exists(p))return;using(var k=Registry.CurrentUser.OpenSubKey(@"Control Panel\Cursors")){object v=k.GetValue("CursorBaseSize");File.WriteAllText(p,v==null?"ausente":v.ToString());}}
 static void RestoreSize(){string p=Path.Combine(data,"tamanho-anterior.txt");if(!File.Exists(p))return;using(var k=Registry.CurrentUser.CreateSubKey(@"Control Panel\Cursors")){string v=File.ReadAllText(p);if(v=="ausente")k.DeleteValue("CursorBaseSize",false);else k.SetValue("CursorBaseSize",int.Parse(v),RegistryValueKind.DWord);}}
 void LoadPreferences(){try{string p=Path.Combine(data,"preferencias.txt");if(!File.Exists(p))return;string[] v=File.ReadAllLines(p);Color c=Color.FromArgb(int.Parse(v[0]));int si=Array.IndexOf(SupportedSizes,int.Parse(v[1]));int st=int.Parse(v[2]);if(si>=0)sizes.SelectedIndex=si;if(st>=0&&st<styles.Items.Count)styles.SelectedIndex=st;for(int i=0;i<palette.Length;i++)if(palette[i].ToArgb()==c.ToArgb()){colors.SelectedIndex=i;chosen=c;return;}chosen=c;preview.Invalidate();}catch{}}
 static void Reload(){SystemParametersInfo(0x57,0,IntPtr.Zero,0);}
 static void Apply(Color c,int size,int style){string dest=Path.Combine(data,c.ToArgb().ToString("X8")+"-"+size+"-s"+style+"-v4");Directory.CreateDirectory(dest);foreach(string f in files){string p=Path.Combine(dest,f);File.WriteAllBytes(p,(f=="Pointer.cur"||f=="Link.cur")?PointerStyles.CursorFile(c,size,style):ConvertFile(Path.Combine(root,"Base",f),c,size));IntPtr h=LoadCursorFromFile(p);if(h==IntPtr.Zero)throw new Exception("Falha ao validar "+f);DestroyCursor(h);}Backup();BackupSize();using(var k=Registry.CurrentUser.CreateSubKey(@"Control Panel\Cursors")){k.SetValue("CursorBaseSize",size,RegistryValueKind.DWord);for(int i=0;i<roles.Length;i++)k.SetValue(roles[i],Path.Combine(dest,files[i]),RegistryValueKind.String);}ApplySize(dest,size);File.WriteAllLines(Path.Combine(data,"preferencias.txt"),new string[]{c.ToArgb().ToString(),size.ToString(),style.ToString()});StartGuard();}
 static void Restore(){StopGuard();string p=Path.Combine(data,"anterior.dat");if(!File.Exists(p))throw new Exception("Nenhuma alteração foi aplicada por este aplicativo ainda.");using(var k=Registry.CurrentUser.CreateSubKey(@"Control Panel\Cursors"))using(var r=new BinaryReader(File.OpenRead(p))){foreach(string role in roles){bool exists=r.ReadBoolean();string v=r.ReadString();var kind=(RegistryValueKind)r.ReadInt32();if(exists)k.SetValue(role,v,kind);else k.DeleteValue(role,false);}}RestoreSize();Reload();}
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();if(args.Length>0&&args[0]=="--guard"){RunGuard();return;}if(args.Length>0&&args[0]=="--test-persistence"){TestPersistence();return;}if(args.Length>0&&args[0]=="--verify"){Directory.CreateDirectory(Path.Combine(root,"Verificacao"));int total=0;foreach(int size in SupportedSizes)foreach(string f in files){string p=Path.Combine(root,"Verificacao",size+"-"+f);File.WriteAllBytes(p,ConvertFile(Path.Combine(root,"Base",f),palette[0],size));IntPtr h=LoadCursorFromFile(p);if(h==IntPtr.Zero)throw new Exception("Inválido: "+p);DestroyCursor(h);total++;}File.WriteAllText(Path.Combine(root,"verificacao.txt"),total+" cursores roxos validados pelo Windows; registro não alterado.");return;}Application.Run(new CursorCores());}
